fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    if word.is_empty() {
        // As per problem statement, input is non-empty, so this case is just a fallback.
        return word;
    }

    let mut result = word.clone();

    // Check the first character:
    // If uppercase, leave it as is.
    // If lowercase, replace with 'A'.
    if !result[0].is_uppercase() {
        result[0] = 'A';
    }

    result
}